 41|     memberId: string | undefined,
 42|     hiveId: string,
 43|     input: { product?: unknown; productId?: unknown; startDate?: unknown; endDate?: unknown },
 44|   ): Treatment {
 45|     const ownerId = requireMember(memberId);
 46|     const hive = this.findHive(hiveId);
 47|     if (hive.ownerId !== ownerId) {
 48|       throw new DomainError("forbidden", "Only the hive owner can record treatments");
 49|     }
 50|     const productId = requireString(input.productId ?? input.product, "productId");
 51|     if (!this.products.findById(productId)) {
 52|       throw new DomainError("validation", "Unknown treatment product");
 53|     }
 54|     const startDate = requireDate(input.startDate);
 55|     const endDate = requireDate(input.endDate);
 56|     if (Date.parse(endDate) < Date.parse(startDate)) {
 57|       throw new DomainError("validation", "endDate must not be before startDate");
 58|     }
 59|     return this.treatments.create({ hiveId, productId, startDate, endDate });
 60|   }
